/* src/app/globals.css */

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ─────────────────────────────────────────────────────────────────────────────
   CSS CUSTOM PROPERTIES
───────────────────────────────────────────────────────────────────────────── */

:root {
  --font-inter: "Inter", system-ui, sans-serif;

  /* Glassmorphism tokens */
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-blur: 24px;

  /* Surface tokens */
  --surface-0: #0a0a0f;
  --surface-1: #0f0f18;
  --surface-2: #161623;
  --surface-3: #1e1e2e;
}

/* ─────────────────────────────────────────────────────────────────────────────
   BASE RESETS
───────────────────────────────────────────────────────────────────────────── */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
}

/* ─────────────────────────────────────────────────────────────────────────────
   CUSTOM SCROLLBAR
───────────────────────────────────────────────────────────────────────────── */

::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 9999px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* ─────────────────────────────────────────────────────────────────────────────
   MARQUEE ANIMATION (Business Marquee template ticker)
───────────────────────────────────────────────────────────────────────────── */

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

.animate-marquee {
  animation: marquee 20s linear infinite;
  display: flex;
  /* Width is doubled in JSX via duplicate content */
}

/* ─────────────────────────────────────────────────────────────────────────────
   GLASSMORPHISM UTILITY
───────────────────────────────────────────────────────────────────────────── */

@layer utilities {
  .glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(var(--glass-blur));
    -webkit-backdrop-filter: blur(var(--glass-blur));
  }

  .glass-dark {
    background: rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.06);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
  }

  /* Noise texture overlay (used in name cards) */
  .noise-overlay::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E");
    pointer-events: none;
    opacity: 0.4;
  }

  /* Gradient text */
  .gradient-text-indigo {
    background: linear-gradient(135deg, #818cf8, #6366f1, #4f46e5);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* Mesh gradient background */
  .mesh-bg {
    background-color: #050014;
    background-image:
      radial-gradient(at 40% 20%, #6366f120 0px, transparent 50%),
      radial-gradient(at 80% 0%, #06b6d415 0px, transparent 50%),
      radial-gradient(at 0% 50%, #8b5cf615 0px, transparent 50%),
      radial-gradient(at 80% 50%, #0ea5e910 0px, transparent 50%),
      radial-gradient(at 0% 100%, #a855f715 0px, transparent 50%);
  }
}

/* ─────────────────────────────────────────────────────────────────────────────
   FOCUS RING — Accessible keyboard navigation
───────────────────────────────────────────────────────────────────────────── */

:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
  border-radius: 4px;
}

/* ─────────────────────────────────────────────────────────────────────────────
   PRINT STYLES — Clean name card printing
───────────────────────────────────────────────────────────────────────────── */

@media print {
  nav,
  footer,
  button,
  [aria-hidden] {
    display: none !important;
  }

  body {
    background: white !important;
    color: black !important;
  }
}

/* ── Template-specific animations ───────────────────────────────────────── */

/* Fade in up — used by wedding hero text */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
.animate-fade-in-up {
  animation: fadeInUp 0.8s ease-out both;
}

/* Pulse glow — used by Celestial star elements */
@keyframes pulseGlow {
  0%, 100% { opacity: 0.4; }
  50%       { opacity: 1;   }
}
.animate-pulse-glow {
  animation: pulseGlow 3s ease-in-out infinite;
}

/* Shimmer — used by Titanium metallic surface */
@keyframes shimmer {
  0%   { background-position: -200% center; }
  100% { background-position:  200% center; }
}
.animate-shimmer {
  background-size: 200% auto;
  animation: shimmer 3s linear infinite;
}

/* Float — gentle up-down for decorative elements */
@keyframes float {
  0%, 100% { transform: translateY(0);   }
  50%       { transform: translateY(-8px); }
}
.animate-float {
  animation: float 4s ease-in-out infinite;
}

/* Slow spin — for decorative rings */
@keyframes spinSlow {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
.animate-spin-slow {
  animation: spinSlow 20s linear infinite;
}

/* Typewriter cursor blink — used by Forge terminal template */
@keyframes blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}
.animate-blink {
  animation: blink 1s step-end infinite;
}
